    #[test]
    fn newly_created_group_keeps_parent_identity_before_its_children_after_save() {
        let source = workbook_without_drawings();
        let mut editor = XlsxEditor::new(&source).unwrap();
        let mut edited = editor.workbook().clone();
        for index in 0..2 {
            let mut child = simple_added_shape(&format!("Child {index}"));
            child.non_visual_id = Some(3 + index);
            child.grouped = true;
            child.group_name = Some("Copied group".into());
            child.group_non_visual_id = Some(2);
            child.group_transform = Some(crate::ir::GroupTransform {
                offset: (0, 0), extent: (1_000_000, 1_000_000),
                child_offset: (0, 0), child_extent: (1_000_000, 1_000_000),
            });
            child.group_child_transform = Some((i64::from(index) * 200_000, 0, 100_000, 100_000));
            child.metadata = Some(crate::ir::DrawingMetadata {
                title: Some(format!("Child title {index}")), ..Default::default()
            });
            edited.sheets[0].drawings.push(child);
        }
        // The browser can copy this IR through JSON before sending it to save.
        let edited = serde_json::from_value(serde_json::to_value(edited).unwrap()).unwrap();
        editor.apply_workbook(&edited).unwrap();
        let saved = editor.save().unwrap();
        let reopened = crate::parse_xlsx(&saved).unwrap();
        let children = &reopened.sheets[0].drawings;
        assert_eq!(children.len(), 2);
        for (index, child) in children.iter().enumerate() {
            assert!(child.grouped);
            assert_eq!(child.group_non_visual_id, Some(2));
            assert_eq!(child.non_visual_id, Some(3 + index as u32));
            assert_eq!(child.group_name.as_deref(), Some("Copied group"));
            assert_eq!(child.metadata.as_ref().unwrap().title, Some(format!("Child title {index}")));
        }
        let untouched = XlsxEditor::new(&saved).unwrap().save().unwrap();
        assert_eq!(untouched, saved);
    }



    #[test]
    fn grouped_anchor_order_uses_the_first_ranked_child_when_parent_is_not_in_ir() {
        let xml = r#"<xdr:wsDr xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing" xmlns:u="urn:future"><xdr:twoCellAnchor u:keep="group"><xdr:grpSp><xdr:nvGrpSpPr><xdr:cNvPr id="4" name="Bundle"/></xdr:nvGrpSpPr><xdr:sp><xdr:cNvPr id="2" name="Left"/></xdr:sp><xdr:sp><xdr:cNvPr id="3" name="Right"/></xdr:sp></xdr:grpSp></xdr:twoCellAnchor><xdr:twoCellAnchor u:keep="chart"><xdr:graphicFrame><xdr:cNvPr id="5" name="Chart"/></xdr:graphicFrame></xdr:twoCellAnchor><xdr:extLst u:keep="extension"/></xdr:wsDr>"#;
        for (order, group_first) in [
            (vec!["Left", "Right", "Chart"], true),
            (vec!["Chart", "Left", "Right"], false),
            (vec!["Bundle", "Chart"], true),
        ] {
            let order = order.into_iter().map(str::to_owned).collect::<Vec<_>>();
            let patched = patch_drawing_order(xml, &order).unwrap();
            assert_eq!(patched.find("name=\"Bundle\"").unwrap() < patched.find("name=\"Chart\"").unwrap(), group_first);
            assert!(patched.contains("u:keep=\"group\""));
            assert!(patched.contains("u:keep=\"chart\""));
            assert!(patched.contains("<xdr:extLst u:keep=\"extension\"/>"));
            assert_eq!(drawing_shape_ids(&patched).unwrap().len(), 4);
            assert_eq!(patch_drawing_order(&patched, &order).unwrap(), patched);
        }
    }

    #[test]
    fn existing_group_parent_and_children_rebase_without_identity_collisions() {
        let source = workbook_without_drawings();
        let mut editor = XlsxEditor::new(&source).unwrap();
        let mut edited = editor.workbook().clone();
        for index in 0..2 {
            let mut child = simple_added_shape(&format!("Child {index}"));
            child.non_visual_id = Some(3 + index);
            child.grouped = true;
            child.group_name = Some("Retained group".into());
            child.group_non_visual_id = Some(2);
            child.group_transform = Some(crate::ir::GroupTransform {
                offset: (0, 0), extent: (1_000_000, 1_000_000),
                child_offset: (0, 0), child_extent: (1_000_000, 1_000_000),
            });
            child.group_child_transform = Some((i64::from(index) * 200_000, 0, 100_000, 100_000));
            edited.sheets[0].drawings.push(child);
        }
        editor.apply_workbook(&edited).unwrap();
        let source = editor.save().unwrap();
        for parent_only in [false, true] {
            let mut editor = XlsxEditor::new(&source).unwrap();
            let mut edited = editor.workbook().clone();
            for (index, child) in edited.sheets[0].drawings.iter_mut().enumerate() {
                child.group_non_visual_id = Some(if parent_only { 9 } else { 3 });
                if !parent_only { child.non_visual_id = Some(4 + index as u32); }
            }
            editor.apply_workbook(&edited).unwrap();
            assert!(editor.has_edits());
            let saved = editor.save().unwrap();
            let reopened = crate::parse_xlsx(&saved).unwrap();
            let children = &reopened.sheets[0].drawings;
            assert_eq!(children.len(), 2);
            for (index, child) in children.iter().enumerate() {
                assert!(child.grouped);
                assert_eq!(child.group_name.as_deref(), Some("Retained group"));
                assert_eq!(child.group_non_visual_id, Some(if parent_only { 9 } else { 3 }));
                assert_eq!(child.non_visual_id, Some(if parent_only { 3 + index as u32 } else { 4 + index as u32 }));
                assert_eq!(child.group_transform, edited.sheets[0].drawings[index].group_transform);
                assert_eq!(child.group_child_transform, edited.sheets[0].drawings[index].group_child_transform);
            }
            assert_eq!(XlsxEditor::new(&saved).unwrap().save().unwrap(), saved);
        }
    }

