    #[test]
    fn new_style_part_keeps_requested_normal_font_on_first_save() {
        let original = include_bytes!("../../../tests/fixtures/basic_test.xlsx");
        let mut untouched = XlsxEditor::new(original).unwrap();
        untouched.apply_workbook(&untouched.workbook().clone()).unwrap();
        assert_eq!(untouched.save().unwrap(), original);
        for (face, size, expected_face, expected_size, expected_scheme) in [
            (Some("Arial"), Some(10.0), "Arial", 10.0, None),
            (Some("Arial"), None, "Arial", 11.0, None),
            (None, Some(17.0), "Calibri", 17.0, Some("minor")),
        ] {
            let mut editor = XlsxEditor::new(original).unwrap();
            let mut edited = editor.workbook().clone();
            let normal = CellStyle {font_name:face.map(str::to_owned),font_size:size,..Default::default()};
            edited.default_style = normal.clone();
            edited.named_styles = vec![crate::ir::NamedCellStyle {
                name:"Normal".into(),builtin_id:Some(0),source_id:0,number_format_id:0,style:normal,
            }];
            editor.apply_workbook(&edited).unwrap();
            let saved = editor.save().unwrap();
            let restored = parse_xlsx(&saved).unwrap();
            assert_eq!(restored.default_style.latin_font_name(), Some(expected_face));
            assert_eq!(restored.default_style.font_size, Some(expected_size));
            assert_eq!(restored.default_style.font_reference.as_ref().and_then(|r|r.scheme.as_deref()),expected_scheme);
            let mut archive = ZipArchive::new(Cursor::new(&saved)).unwrap();
            let mut xml = String::new();
            archive.by_name("xl/styles.xml").unwrap().read_to_string(&mut xml).unwrap();
            let nodes = style_xml_nodes(&xml).unwrap();
            let section = nodes.iter().position(|n|n.standard && n.name=="fonts").unwrap();
            let font = nodes.iter().find(|n|n.standard && n.name=="font" && n.parent==Some(section)).unwrap();
            let raw = &xml[font.start..font.end];
            assert!(raw.contains(&format!("name val=\"{expected_face}\"")));
            assert_eq!(raw.contains("<scheme"), expected_scheme.is_some());
            let mut again = XlsxEditor::new(&saved).unwrap();
            again.apply_workbook(&again.workbook().clone()).unwrap();
            assert_eq!(again.save().unwrap(), saved);
        }
    }

    #[test]
    fn workbook_named_normal_font_changes_survive_save() {
        let original=include_bytes!("../../../tests/fixtures/vba/array_argument_rank.xlsm");
        let mut untouched=XlsxEditor::new(original).unwrap();
        untouched.apply_workbook(&untouched.workbook().clone()).unwrap();
        assert_eq!(untouched.save().unwrap(),original);
        let mut editor=XlsxEditor::new(original).unwrap();
        let mut edited=editor.workbook().clone();
        let normal=edited.named_styles.iter_mut().find(|style|style.builtin_id==Some(0)).unwrap();
        normal.style.font_size=Some(26.0);
        edited.sheets[0].rows.iter_mut().find(|row|row.index==1).unwrap().cells.iter_mut()
            .find(|cell|cell.col==1).unwrap().style.font_size=Some(26.0);
        editor.apply_workbook(&edited).unwrap();
        assert!(editor.has_edits());
        let saved=editor.save().unwrap();
        let first_font_size = |bytes: &[u8]| {
            let mut zip = ZipArchive::new(Cursor::new(bytes)).unwrap();
            let mut xml = String::new();
            zip.by_name("xl/styles.xml").unwrap().read_to_string(&mut xml).unwrap();
            let nodes = style_xml_nodes(&xml).unwrap();
            let section = nodes.iter().position(|n| n.standard && n.name == "fonts").unwrap();
            let font = nodes.iter().position(|n| n.standard && n.parent == Some(section) && n.name == "font").unwrap();
            let size = nodes.iter().find(|n| n.standard && n.parent == Some(font) && n.name == "sz").unwrap();
            style_node_number(&xml,size,"val").unwrap()
        };
        assert_eq!(first_font_size(&saved),26,"Excel reads Normal from physical font0");
        let restored=parse_xlsx(&saved).unwrap();
        let normal=restored.named_styles.iter().find(|style|style.builtin_id==Some(0)).unwrap();
        assert_eq!(normal.style.font_size,Some(26.0));
        let first=&restored.sheets[0].rows.iter().find(|row|row.index==1).unwrap().cells;
        assert_eq!(first.iter().find(|cell|cell.col==1).unwrap().style.font_size,Some(26.0));
        // The explicitly bold font is a different font identity.
        assert_eq!(first.iter().find(|cell|cell.col==0).unwrap().style.font_size,Some(11.0));
        let mut again=XlsxEditor::new(&saved).unwrap();
        let mut edited=again.workbook().clone();
        edited.named_styles.iter_mut().find(|style|style.builtin_id==Some(0)).unwrap().style.font_size=Some(32.0);
        again.apply_workbook(&edited).unwrap();
        let saved_again=again.save().unwrap();
        assert_eq!(first_font_size(&saved_again),32,"repeated Normal edits must retain physical font0");
        let restored=parse_xlsx(&saved_again).unwrap();
        let first=&restored.sheets[0].rows.iter().find(|row|row.index==1).unwrap().cells;
        assert_eq!(first.iter().find(|cell|cell.col==1).unwrap().style.font_size,Some(32.0));
        assert_eq!(first.iter().find(|cell|cell.col==0).unwrap().style.font_size,Some(11.0));
    }

    #[test]
    fn explicit_font_edits_replace_inherited_name_and_color_origins() {
        let original=include_bytes!("../../../tests/fixtures/vba/array_argument_rank.xlsm");
        for whole_workbook in [false,true] {
            let mut editor=XlsxEditor::new(original).unwrap();
            let mut edited=editor.workbook().clone();
            let cell=edited.sheets[0].rows.iter_mut().find(|r|r.index==1).unwrap()
                .cells.iter_mut().find(|c|c.col==0).unwrap();
            cell.style.font_name=Some("Meiryo".into());
            cell.style.font_color=Some("0070C0".into());
            cell.style.font_size=Some(18.0);
            if whole_workbook {
                editor.apply_workbook(&edited).unwrap();
            } else {
                editor.set_cell_style(0,1,0,cell.style.clone());
            }
            let saved=editor.save().unwrap();
            let restored=parse_xlsx(&saved).unwrap();
            let style=&restored.sheets[0].rows.iter().find(|r|r.index==1).unwrap()
                .cells.iter().find(|c|c.col==0).unwrap().style;
            assert_eq!(style.font_name.as_deref(),Some("Meiryo"));
            assert_eq!(style.latin_font_name(),Some("Meiryo"));
            assert_eq!(style.font_color.as_deref(),Some("0070C0"));
            assert_eq!(style.font_size,Some(18.0));

            let mut editor=XlsxEditor::new(&saved).unwrap();
            let mut edited=editor.workbook().clone();
            let cell=edited.sheets[0].rows.iter_mut().find(|r|r.index==1).unwrap()
                .cells.iter_mut().find(|c|c.col==0).unwrap();
            cell.style.font_name=None;
            cell.style.font_color=None;
            cell.style.font_size=Some(8.0);
            if whole_workbook {
                editor.apply_workbook(&edited).unwrap();
            } else {
                editor.set_cell_style(0,1,0,cell.style.clone());
            }
            let restored=parse_xlsx(&editor.save().unwrap()).unwrap();
            let style=&restored.sheets[0].rows.iter().find(|r|r.index==1).unwrap()
                .cells.iter().find(|c|c.col==0).unwrap().style;
            assert_eq!(style.font_name,restored.default_style.font_name);
            assert_eq!(style.font_color,None);
            assert_eq!(style.font_size,Some(8.0));
        }
    }

    #[test]
    fn saving_sparse_font_edits_retains_default_theme_face() {
        let original=include_bytes!("../../../tests/fixtures/vba/array_argument_rank.xlsm");
        for whole_workbook in [false,true] {
            for explicit_face in [false,true] {
                for explicit_color in [false,true] {
                    let mut editor=XlsxEditor::new(original).unwrap();
                    let default=editor.workbook().default_style.clone();
                    let mut style=CellStyle {font_size:Some(12.5),..Default::default()};
                    if explicit_face {style.font_name=Some("Meiryo".into());}
                    if explicit_color {
                        style.font_reference=Some(Box::new(crate::ir::FontReference {
                            theme:Some(4),..Default::default()
                        }));
                    }
                    if whole_workbook {
                        let mut edited=editor.workbook().clone();
                        edited.sheets[0].rows.iter_mut().find(|r|r.index==1).unwrap()
                            .cells.iter_mut().find(|c|c.col==0).unwrap().style=style;
                        editor.apply_workbook(&edited).unwrap();
                    } else {
                        editor.set_cell_style(0,1,0,style);
                    }
                    let saved=editor.save().unwrap();
                    let restored=parse_xlsx(&saved).unwrap();
                    let actual=&restored.sheets[0].rows.iter().find(|r|r.index==1).unwrap()
                        .cells.iter().find(|c|c.col==0).unwrap().style;
                    assert_eq!(actual.font_size,Some(12.5));
                    assert_eq!(actual.latin_font_name(),if explicit_face {Some("Meiryo")} else {default.latin_font_name()});
                    assert_eq!(actual.font_reference.as_ref().and_then(|r|r.scheme.as_deref()),
                        if explicit_face {None} else {Some("minor")});
                    assert_eq!(actual.font_reference.as_ref().and_then(|r|r.theme),explicit_color.then_some(4));
                }
            }
        }
    }

    #[test]
    fn editing_bold_preserves_theme_color_and_latin_font_identity() {
        let bytes=include_bytes!("../../../tests/fixtures/vba/array_argument_rank.xlsm");
        let mut editor=XlsxEditor::new(bytes).unwrap();
        let initial=editor.workbook().sheets[0].rows.iter().find(|r|r.index==1).unwrap()
            .cells.iter().find(|c|c.col==0).unwrap().style.clone();
        assert_eq!(initial.latin_font_name(),Some("Aptos Narrow"));
        let reference=initial.font_reference.as_ref().unwrap();
        assert_eq!(reference.scheme.as_deref(),Some("minor"));
        assert_eq!(reference.theme,Some(1));
        assert_eq!(editor.save().unwrap().as_slice(),bytes);
        let mut changed=initial.clone();changed.bold=false;
        editor.set_cell_style(0,1,0,changed);
        let saved=editor.save().unwrap();
        let reloaded=parse_xlsx(&saved).unwrap();
        let actual=&reloaded.sheets[0].rows.iter().find(|r|r.index==1).unwrap()
            .cells.iter().find(|c|c.col==0).unwrap().style;
        assert!(!actual.bold);
        assert_eq!(actual.latin_font_name(),Some("Aptos Narrow"));
        assert_eq!(actual.font_reference,initial.font_reference);
    }

