/// Inspect or rewrite recognized formula slots in a detached import. Unknown
/// XML and chart extension payloads remain byte-identical. Changes are atomic.
pub fn map_worksheet_import_formulas(
    graph: &mut WorksheetPartImport,
    data: &mut WorksheetDataImport,
    mut map: impl FnMut(&[u16]) -> Result<Vec<u16>, XlsxError>,
) -> Result<(), XlsxError> {
    let worksheet = rewrite_imported_formula_values(&data.worksheet.worksheet_xml, &mut map)?;
    let mut changed = HashMap::new();
    let mut paths: Vec<_> = graph.parts.keys().collect();
    paths.sort();
    for part in paths {
        let recognized = graph.content_types.get(part).is_some_and(|kind|
            kind.ends_with(".worksheet+xml") || kind.ends_with(".table+xml") || kind.ends_with(".chart+xml"));
        if !recognized { continue; }
        let original = &graph.parts[part];
        let xml = std::str::from_utf8(original).map_err(|error| XlsxError::InvalidData(error.to_string()))?;
        let updated = rewrite_imported_formula_values(xml, &mut map)?;
        if updated != xml { changed.insert(part.clone(), updated.into_bytes()); }
    }
    graph.parts.extend(changed);
    data.worksheet.worksheet_xml = worksheet;
    Ok(())
}

/// Clone and register selected external-book roots without reconstructing their
/// payloads. `copied_parts` seeds identities already installed by a sheet copy.
/// Reused destination books are selected by the caller and omitted from roots.
pub fn import_workbook_external_link_graphs(
    source_data: &[u8], destination_data: &[u8], roots: &[String],
    copied_parts: &HashMap<String, String>,
) -> Result<(Vec<u8>, Vec<String>), XlsxError> {
    use std::collections::HashSet;
    let fail = |message: &str| XlsxError::InvalidData(message.into());
    if roots.is_empty() { return Ok((destination_data.to_vec(), Vec::new())); }
    let mut source = OoxmlArchive::new(source_data)?;
    let mut destination = OoxmlArchive::new(destination_data)?;
    for names in [source.file_names(), destination.file_names()] {
        let mut seen = HashSet::new();
        if names.iter().any(|name| !seen.insert(name)) { return Err(fail("duplicate package part in external import")); }
    }
    let source_names: HashSet<_> = source.file_names().into_iter().collect();
    let mut occupied: HashSet<_> = destination.file_names().into_iter().collect();
    let mut mapped = copied_parts.clone();
    let mut destinations = HashSet::new();
    for (old, new) in &mapped {
        if !source_names.contains(old) || !occupied.contains(new) || !destinations.insert(new.to_ascii_lowercase()) {
            return Err(fail("invalid seeded external import identity"));
        }
    }
    let source_types = source.read_part("[Content_Types].xml")?;
    let mut workbook = destination.read_part("xl/workbook.xml")?;
    let mut relationships = destination.read_part("xl/_rels/workbook.xml.rels")?;
    let mut types = destination.read_part("[Content_Types].xml")?;
    let mut replacements = BTreeMap::<String, Vec<u8>>::new();
    let mut added_types = BTreeMap::<String, String>::new();
    let mut imported = Vec::new();
    let mut asked = HashSet::new();
    let book_nodes = link_xml_nodes(&workbook)?;
    let book_root = link_xml_root(&book_nodes)?;
    let namespace = book_nodes[book_root].namespace.clone();
    let relation_namespace = if namespace == "http://purl.oclc.org/ooxml/spreadsheetml/main" {
        "http://purl.oclc.org/ooxml/officeDocument/relationships"
    } else { "http://schemas.openxmlformats.org/officeDocument/2006/relationships" };
    for root in roots {
        if !asked.insert(root) { return Err(fail("duplicate requested external import root")); }
        if !content_type_for_part(&source_types, root)?.ends_with(".externalLink+xml") {
            return Err(fail("external import root is not an external-link part"));
        }
        let source_parts = read_part_graph(&mut source, root)?;
        let graph = copy_part_graph_seeded(&source_parts, root, &occupied, &HashSet::new(), &mapped)?;
        for (old, new) in &graph.paths {
            if graph.parts.contains_key(new) {
                added_types.insert(new.clone(), content_type_for_part(&source_types, old)?);
            }
            let new_rels = sheet_rels_path(new);
            if graph.parts.contains_key(&new_rels) {
                added_types.insert(new_rels, content_type_for_part(&source_types, &sheet_rels_path(old))?);
            }
        }
        for (path, bytes) in graph.parts {
            if occupied.iter().any(|held| held.eq_ignore_ascii_case(&path)) {
                return Err(fail("external import part collides with destination"));
            }
            occupied.insert(path.clone());
            replacements.insert(path, bytes);
        }
        let registered = parse_relationships(&relationships).map_err(|error| fail(&error.to_string()))?;
        if registered.values().any(|rel| rel.rel_type.ends_with("/externalLink")
            && resolve_part_target("xl/workbook.xml", &rel.target) == graph.root) {
            return Err(fail("external import root is already registered"));
        }
        let id = link_free_id(&relationships)?;
        relationships = link_relation(&relationships, &id,
            &format!("{relation_namespace}/externalLink"),
            &relative_sheet_target("xl/workbook.xml", &graph.root), false)?;
        let reference = format!("<externalReference xmlns=\"{}\" xmlns:r=\"{}\" r:id=\"{}\"/>",
            escape(&namespace), relation_namespace, escape(&id));
        let nodes = link_xml_nodes(&workbook)?;
        let root_index = link_xml_root(&nodes)?;
        let sections = link_children(&nodes, root_index, "externalReferences");
        if sections.len() > 1 { return Err(fail("duplicate workbook external reference lists")); }
        workbook = if let Some(index) = sections.first() {
            link_insert(&workbook, &nodes[*index], nodes[*index].close, &reference)?
        } else {
            let section = format!("<externalReferences xmlns=\"{}\">{reference}</externalReferences>", escape(&namespace));
            let at = nodes.iter().filter(|node| node.parent == Some(root_index)
                && node.namespace == namespace && matches!(node.name.as_str(),"sheets"|"functionGroups"))
                .map(|node| node.end).max().unwrap_or(nodes[root_index].head);
            link_insert(&workbook, &nodes[root_index], at, &section)?
        };
        imported.push(graph.root);
        mapped = graph.paths;
    }
    if added_types.len() != replacements.len() { return Err(fail("external import part has no content type")); }
    let records = added_types.iter().map(|(path, kind)| format!(
        "<Override xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\" PartName=\"/{}\" ContentType=\"{}\"/>",
        escape(path),escape(kind))).collect::<String>();
    let type_nodes = link_xml_nodes(&types)?;
    let type_root = link_xml_root(&type_nodes)?;
    types = link_insert(&types, &type_nodes[type_root], type_nodes[type_root].close, &records)?;
    replacements.insert("xl/workbook.xml".into(), workbook.into_bytes());
    replacements.insert("xl/_rels/workbook.xml.rels".into(), relationships.into_bytes());
    replacements.insert("[Content_Types].xml".into(), types.into_bytes());
    let mut input = ZipArchive::new(Cursor::new(destination_data)).map_err(|error| fail(&error.to_string()))?;
    let mut output = ZipWriter::new(Cursor::new(Vec::new()));
    for index in 0..input.len() {
        let entry = input.by_index(index).map_err(|error| fail(&error.to_string()))?;
        let name = entry.name().to_string();
        if let Some(bytes) = replacements.remove(&name) {
            output.start_file(name, SimpleFileOptions::default().compression_method(zip::CompressionMethod::Deflated))
                .map_err(|error| fail(&error.to_string()))?;
            output.write_all(&bytes).map_err(|error| fail(&error.to_string()))?;
        } else { output.raw_copy_file(entry).map_err(|error| fail(&error.to_string()))?; }
    }
    for (path, bytes) in replacements {
        output.start_file(path, SimpleFileOptions::default().compression_method(zip::CompressionMethod::Deflated))
            .map_err(|error| fail(&error.to_string()))?;
        output.write_all(&bytes).map_err(|error| fail(&error.to_string()))?;
    }
    Ok((output.finish().map_err(|error| fail(&error.to_string()))?.into_inner(), imported))
}

