#[cfg(test)]
mod external_graph_import_tests {
    use super::*;
    const BASE: &[u8] = include_bytes!("../../../tests/fixtures/basic_test.xlsx");
    const A: &str = "xl/externalLinks/linkA.xml";
    const B: &str = "xl/externalLinks/linkB.xml";
    const SHEET: &str = "xl/worksheets/sheet1.xml";
    fn entries(bytes: &[u8]) -> BTreeMap<String,Vec<u8>> {
        let mut archive=ZipArchive::new(Cursor::new(bytes)).unwrap();
        let mut result=BTreeMap::new();
        for index in 0..archive.len() {
            let mut entry=archive.by_index(index).unwrap();let name=entry.name().to_string();
            let mut data=Vec::new();entry.read_to_end(&mut data).unwrap();
            assert!(result.insert(name,data).is_none(),"duplicate ZIP entry");
        }
        result
    }
    fn package(extra: BTreeMap<String,Vec<u8>>) -> Vec<u8> {
        let mut all=entries(BASE);all.extend(extra);
        let mut writer=ZipWriter::new(Cursor::new(Vec::new()));
        for (path,bytes) in all {
            writer.start_file(path,SimpleFileOptions::default()).unwrap();
            writer.write_all(&bytes).unwrap();
        }
        writer.finish().unwrap().into_inner()
    }
    fn source(broken: bool) -> Vec<u8> {
        let mut parts=BTreeMap::new();
        for (part,value) in [(A,700),(B,900)] {
            let xml=format!(r#"<externalLink xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:u="urn:opaque" u:keep="root"><externalBook r:id="rId1"><sheetNames><sheetName val="Remote"/></sheetNames><sheetDataSet><sheetData sheetId="0"><row r="1"><cell r="A1" t="n"><v>{value}</v></cell></row></sheetData></sheetDataSet></externalBook><extLst><ext uri="opaque"><u:kept>_xD800_</u:kept></ext></extLst></externalLink>"#);
            parts.insert(part.into(),xml.into_bytes());
            let shared=if broken {"../opaque/missing.bin"}else{"../opaque/shared.bin"};
            let rels=format!(r#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships" xmlns:u="urn:opaque"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/externalLinkPath" Target="peer.xlsx" TargetMode="External"/><Relationship Id="rId2" Type="urn:opaque/shared" Target="{shared}" u:keep="yes"/><Relationship Id="rId3" Type="urn:opaque/sheet" Target="../worksheets/sheet1.xml#anchor"/><Relationship Id="rId9" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/externalLinkPath" Target="file:///C:/source/peer.xlsx" TargetMode="External"/></Relationships>"#);
            parts.insert(sheet_rels_path(part),rels.into_bytes());
        }
        parts.insert("xl/opaque/shared.bin".into(),vec![0,255,1,0,128]);
        parts.insert("xl/opaque/_rels/shared.bin.rels".into(),br#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="cycle" Type="urn:opaque/cycle" Target="../externalLinks/linkA.xml"/></Relationships>"#.to_vec());
        let original=entries(BASE);let types=String::from_utf8(original["[Content_Types].xml"].clone()).unwrap();
        let overrides=format!(r#"<Override PartName="/{A}" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.externalLink+xml"/><Override PartName="/{B}" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.externalLink+xml"/><Override PartName="/xl/opaque/shared.bin" ContentType="application/octet-stream"/>"#);
        assert!(types.contains("</Types>"));
        parts.insert("[Content_Types].xml".into(),types.replace("</Types>",&format!("{overrides}</Types>")).into_bytes());
        package(parts)
    }
    #[test]
    fn imported_external_graph_keeps_shared_cycles_seeded_sheets_and_opaque_bytes() {
        let source=source(false);let before_source=source.clone();let before=entries(BASE);
        let seeds=HashMap::from([(SHEET.to_string(),SHEET.to_string())]);
        let (output,roots)=import_workbook_external_link_graphs(&source,BASE,&[A.into(),B.into()],&seeds).unwrap();
        assert_eq!(source,before_source);assert_eq!(roots.len(),2);
        let after=entries(&output);let original=entries(&source);
        for (path,bytes) in before {
            if !matches!(path.as_str(),"xl/workbook.xml"|"xl/_rels/workbook.xml.rels"|"[Content_Types].xml") {assert_eq!(after[&path],bytes,"{path}");}
        }
        assert_eq!(after[&roots[0]],original[A]);assert_eq!(after[&roots[1]],original[B]);
        let blob=after.keys().filter(|name|name.starts_with("xl/opaque/")&&name.ends_with(".bin")).collect::<Vec<_>>();
        assert_eq!(blob.len(),1);assert_eq!(after[blob[0]],vec![0,255,1,0,128]);
        for root in &roots {
            let rels=String::from_utf8(after[&sheet_rels_path(root)].clone()).unwrap();
            let parsed=parse_relationships(&rels).unwrap();
            assert_eq!(resolve_part_target(root,&parsed["rId2"].target),*blob[0]);
            assert_eq!(parsed["rId3"].target.split('#').nth(1),Some("anchor"));
            assert_eq!(resolve_part_target(root,parsed["rId3"].target.split('#').next().unwrap()),SHEET);
            assert_eq!(parsed["rId1"].target,"peer.xlsx");
            assert_eq!(parsed["rId9"].target,"file:///C:/source/peer.xlsx");
            assert!(rels.contains("u:keep=\"yes\""));
        }
        let rels=String::from_utf8(after[&sheet_rels_path(blob[0])].clone()).unwrap();
        assert_eq!(resolve_part_target(blob[0],&parse_relationships(&rels).unwrap()["cycle"].target),roots[0]);
        let parsed=crate::parse_xlsx_preserving_values(&output).unwrap();
        assert_eq!(parsed.external_books.len(),2);
        assert_eq!(parsed.external_books[0].origin_part.as_deref(),Some(roots[0].as_str()));
        assert_eq!(parsed.external_books[1].origin_part.as_deref(),Some(roots[1].as_str()));
        assert_eq!(parsed.external_books[0].sheets[0].cells[0].2,CellValue::Number(700.0));
        assert_eq!(parsed.external_books[1].sheets[0].cells[0].2,CellValue::Number(900.0));
    }
    #[test]
    fn imported_external_graph_rejects_missing_parts_and_invalid_seeds() {
        assert!(import_workbook_external_link_graphs(&source(true),BASE,&[A.into()],&HashMap::new()).is_err());
        assert!(import_workbook_external_link_graphs(&source(false),BASE,&[A.into()],
            &HashMap::from([(SHEET.into(),"xl/worksheets/missing.xml".into())])).is_err());
        assert!(import_workbook_external_link_graphs(&source(false),BASE,&[A.into(),A.into()],&HashMap::new()).is_err());
    }
    fn swap_books(units:&[u16])->Result<Vec<u16>,XlsxError> {
        oxicells_calc::parser::transform_utf16_formula(units,|formula|
            oxicells_calc::lexer::map_formula_sheet_references(formula,|sheet| {
                let (book,name)=sheet.strip_prefix('[')?.split_once(']')?;
                match book {"1"=>Some(format!("[2]{name}")),"2"=>Some(format!("[1]{name}")),_=>None}
            }).map_err(|error|error.to_string())).map_err(XlsxError::InvalidData)
    }
    #[test]
    fn imported_external_formula_mapping_is_simultaneous_and_preserves_opaque_utf16() {
        let xml=r#"<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:u="urn:opaque"><sheetData><row r="1"><c r="A1"><f>[1]Remote!A1+[2]Other!A2+&quot;_xD800_[1]literal&quot;</f></c></row></sheetData><u:f>[1]opaque!A1</u:f></worksheet>"#;
        let changed=rewrite_imported_formula_values(xml,&mut swap_books).unwrap();
        assert!(changed.contains("_xD800_[1]literal"));
        assert!(changed.contains("<u:f>[1]opaque!A1</u:f>"));
        let mut values=Vec::new();rewrite_imported_formula_values(&changed,&mut |units|{values.push(units.to_vec());Ok(units.to_vec())}).unwrap();
        assert_eq!(values.len(),1);
        let mut expected:Vec<u16>="[2]Remote!A1+[1]Other!A2+\"".encode_utf16().collect();
        expected.push(0xd800);expected.extend("[1]literal\"".encode_utf16());
        assert_eq!(oxicells_calc::parser::parse_utf16(&values[0]),oxicells_calc::parser::parse_utf16(&expected));
        let chart=r#"<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart"><c:chart><c:ser><c:val><c:numRef><c:f>[1]Remote!A1</c:f></c:numRef></c:val></c:ser></c:chart><c:extLst><c:ext uri="opaque"><c:numRef><c:f>[1]opaque!A1</c:f></c:numRef></c:ext></c:extLst></c:chartSpace>"#;
        let updated=rewrite_imported_formula_values(chart,&mut swap_books).unwrap();
        assert!(updated.contains("<c:extLst><c:ext uri=\"opaque\"><c:numRef><c:f>[1]opaque!A1</c:f></c:numRef></c:ext></c:extLst>"));
        assert_ne!(updated,chart);
    }
    #[test]
    fn imported_external_formula_mapping_leaves_inputs_unchanged_on_failure() {
        let xml=r#"<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData><row r="1"><c r="A1"><f>[1]Remote!A1</f></c></row></sheetData></worksheet>"#;
        let styles=r#"<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="1"><font><sz val="11"/><name val="Calibri"/></font></fonts><fills count="1"><fill><patternFill patternType="none"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>"#;
        let copied=worksheet_copy_styles(xml,&styles).unwrap();
        let mut data=plan_worksheet_data_import(xml,&copied,&styles,None,None).unwrap();
        let mut graph=WorksheetPartImport {
            root_part:SHEET.into(),source_parts:HashMap::from([(SHEET.into(),SHEET.into())]),
            parts:HashMap::from([(SHEET.into(),xml.as_bytes().to_vec())]),
            content_types:HashMap::from([(SHEET.into(),"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml".into())]),
        };
        let before_parts=graph.parts.clone();let before_sheet=data.worksheet.worksheet_xml.clone();
        let mut calls=0;
        let result=map_worksheet_import_formulas(&mut graph,&mut data,|units|{
            calls+=1;if calls==2 {return Err(XlsxError::InvalidData("deliberate mapping failure".into()));}
            swap_books(units)
        });
        assert!(result.is_err());assert_eq!(calls,2);
        assert_eq!(graph.parts,before_parts);assert_eq!(data.worksheet.worksheet_xml,before_sheet);
    }
}

