/// Rewrite only recognized formula slots of selected, already-installed parts.
/// This preserves column defaults and edits made after the detached import was
/// planned, while leaving destination parts outside the copied graph intact.
pub fn map_imported_part_formulas(
    package: &[u8], parts: &[String],
    mut map: impl FnMut(&[u16]) -> Result<Vec<u16>, XlsxError>,
) -> Result<Vec<u8>, XlsxError> {
    let fail=|message:&str|XlsxError::InvalidData(message.into());
    if parts.is_empty() {return Ok(package.to_vec())}
    let mut archive=OoxmlArchive::new(package)?;
    let types=archive.read_part("[Content_Types].xml")?;
    let mut seen=std::collections::HashSet::new();
    let mut changed=BTreeMap::new();
    for part in parts {
        if !seen.insert(part) {continue;}
        let kind=content_type_for_part(&types,part)?;
        if !kind.ends_with(".worksheet+xml")&&!kind.ends_with(".table+xml")&&!kind.ends_with(".chart+xml") {continue;}
        let bytes=archive.read_binary_part(part)?;
        let xml=std::str::from_utf8(&bytes).map_err(|error|fail(&error.to_string()))?;
        let updated=rewrite_imported_formula_values(xml,&mut map)?;
        if updated!=xml {changed.insert(part.clone(),updated.into_bytes());}
    }
    if changed.is_empty() {return Ok(package.to_vec())}
    let mut input=ZipArchive::new(Cursor::new(package)).map_err(|error|fail(&error.to_string()))?;
    let mut output=ZipWriter::new(Cursor::new(Vec::new()));
    for index in 0..input.len() {
        let entry=input.by_index(index).map_err(|error|fail(&error.to_string()))?;
        let name=entry.name().to_string();
        if let Some(bytes)=changed.remove(&name) {
            output.start_file(name,SimpleFileOptions::default().compression_method(zip::CompressionMethod::Deflated))
                .map_err(|error|fail(&error.to_string()))?;
            output.write_all(&bytes).map_err(|error|fail(&error.to_string()))?;
        }else{output.raw_copy_file(entry).map_err(|error|fail(&error.to_string()))?;}
    }
    if !changed.is_empty() {return Err(fail("mapped imported part is missing"));}
    Ok(output.finish().map_err(|error|fail(&error.to_string()))?.into_inner())
}

#[cfg(test)]
mod installed_external_formula_map_tests {
    use super::*;
    #[test]
    fn installed_formula_mapping_keeps_widths_and_maps_aliased_parts_once() {
        let base=include_bytes!("../../../tests/fixtures/basic_test.xlsx");
        let mut input=ZipArchive::new(Cursor::new(base.as_slice())).unwrap();
        let mut original=BTreeMap::new();
        for index in 0..input.len() {
            let mut entry=input.by_index(index).unwrap();let name=entry.name().to_string();
            let mut bytes=Vec::new();entry.read_to_end(&mut bytes).unwrap();original.insert(name,bytes);
        }
        let sheet="xl/worksheets/sheet1.xml";
        let xml=r#"<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetFormatPr defaultColWidth="17.25"/><sheetData><row r="1"><c r="A1"><f>[1]Remote!A1</f></c></row></sheetData></worksheet>"#;
        original.insert(sheet.into(),xml.as_bytes().to_vec());
        let mut writer=ZipWriter::new(Cursor::new(Vec::new()));
        for (path,bytes) in &original {writer.start_file(path,SimpleFileOptions::default()).unwrap();writer.write_all(bytes).unwrap();}
        let package=writer.finish().unwrap().into_inner();let mut calls=0;
        let mapped=map_imported_part_formulas(&package,&[sheet.into(),sheet.into(),"xl/styles.xml".into()],|units|{
            calls+=1;
            oxicells_calc::parser::transform_utf16_formula(units,|formula|
                oxicells_calc::lexer::map_formula_sheet_references(formula,|name|
                    name.strip_prefix("[1]").map(|sheet|format!("[2]{sheet}")))
                    .map_err(|error|error.to_string())).map_err(XlsxError::InvalidData)
        }).unwrap();
        assert_eq!(calls,1);
        let mut archive=ZipArchive::new(Cursor::new(mapped)).unwrap();
        for index in 0..archive.len() {
            let mut entry=archive.by_index(index).unwrap();let name=entry.name().to_string();
            let mut bytes=Vec::new();entry.read_to_end(&mut bytes).unwrap();
            if name==sheet {
                let text=String::from_utf8(bytes).unwrap();assert!(text.contains("defaultColWidth=\"17.25\""));
                assert!(text.contains("[2]Remote"));assert!(!text.contains("[1]Remote"));
            }else{assert_eq!(bytes,original[&name],"{name}");}
        }
        let unchanged=map_imported_part_formulas(&package,&[sheet.into()],|units|Ok(units.to_vec())).unwrap();
        assert_eq!(unchanged,package);
        assert!(map_imported_part_formulas(&package,&[sheet.into()],|_|Err(XlsxError::InvalidData("stop".into()))).is_err());
    }
}
